--
-- Table structure for table `t_perm_menu_action`
--

DROP TABLE IF EXISTS `t_perm_menu_action`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_perm_menu_action` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `menu_id` varchar(36) NOT NULL COMMENT '所属功能点ID',
  `action_code` varchar(64) NOT NULL COMMENT '动作编码，如 view / import / confirm_pay',
  `action_name` varchar(64) NOT NULL COMMENT '动作中文名，如 查看 / 导入 / 确认出款',
  `base_action` int NOT NULL COMMENT '动作基类 1view 2add 3edit 4delete 5approve 6export',
  `action_sort` int NOT NULL DEFAULT '0' COMMENT '动作排序',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_menu_action` (`menu_id`,`action_code`),
  KEY `idx_action_menu` (`menu_id`),
  KEY `idx_action_base` (`base_action`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权限-动作表';
/*!40101 SET character_set_client = @saved_cs_client */;

