DROP TABLE IF EXISTS `t_perm_role`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_perm_role` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `role_name` varchar(50) NOT NULL COMMENT '职位名称',
  `role_code` varchar(64) NOT NULL COMMENT '职位编码，大写字母/数字/下划线，全局唯一',
  `dept_id` varchar(36) DEFAULT NULL COMMENT '所属部门ID',
  `role_type` varchar(20) NOT NULL DEFAULT '业务职位' COMMENT '职位类型 业务职位/管理职位/职能职位/系统职位',
  `is_sys` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否系统预置，预置不可删除',
  `role_status` varchar(10) NOT NULL DEFAULT '启用' COMMENT '职位状态 启用/停用',
  `perm_count` int NOT NULL DEFAULT '0' COMMENT '权限数：该职位在权限树上已勾选动作的总数',
  `sort_no` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) DEFAULT NULL COMMENT '职位定位 / 权限特征说明',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_code` (`role_code`),
  KEY `idx_role_dept` (`dept_id`),
  KEY `idx_role_type` (`role_type`),
  KEY `idx_role_status` (`role_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权限-职位表';
