--
-- Table structure for table `t_student_base`
--

DROP TABLE IF EXISTS `t_student_base`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_student_base` (
  `id` varchar(36) NOT NULL COMMENT '主键UUID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(36) DEFAULT NULL COMMENT '创建人ID',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_by` varchar(36) DEFAULT NULL COMMENT '修改人ID',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `student_no` varchar(32) NOT NULL COMMENT '学号 S20260001',
  `student_name` varchar(50) NOT NULL COMMENT '姓名',
  `gender` int NOT NULL COMMENT '性别 1男 2女',
  `age` int DEFAULT NULL COMMENT '年龄',
  `dept_code` int NOT NULL COMMENT '部门 1初高部 2大学部',
  `class_id` varchar(36) DEFAULT NULL COMMENT '班级ID',
  `class_name` varchar(50) DEFAULT NULL COMMENT '班级名称',
  `head_teacher_id` varchar(36) DEFAULT NULL COMMENT '班主任ID',
  `head_teacher_name` varchar(50) DEFAULT NULL COMMENT '班主任姓名',
  `teacher_id` varchar(36) DEFAULT NULL COMMENT '教员ID',
  `teacher_name` varchar(50) DEFAULT NULL COMMENT '教员姓名',
  `assistant_id` varchar(36) DEFAULT NULL COMMENT '助教ID',
  `assistant_name` varchar(50) DEFAULT NULL COMMENT '助教姓名',
  `student_status` int NOT NULL DEFAULT '1' COMMENT '学生状态 1待咨询2咨询中3试学中4预在读5正式在读6休学7退学8实训中9待就业10已就业11流失',
  `stage` int DEFAULT NULL COMMENT '学习阶段',
  `phone` varchar(20) DEFAULT NULL COMMENT '学生手机号',
  `parent_phone` varchar(20) DEFAULT NULL COMMENT '家长手机号',
  `dorm_id` varchar(36) DEFAULT NULL COMMENT '宿舍ID',
  `dorm_no` varchar(20) DEFAULT NULL COMMENT '宿舍号',
  `education` varchar(50) DEFAULT NULL COMMENT '学历',
  `enroll_date` date DEFAULT NULL COMMENT '入学时间',
  `attendance_rate` decimal(5,2) DEFAULT NULL COMMENT '出勤率',
  `repeat_count` int DEFAULT '0' COMMENT '末班次数',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_no` (`student_no`),
  KEY `idx_class_id` (`class_id`),
  KEY `idx_student_status` (`student_status`),
  KEY `idx_dept_status` (`dept_code`,`student_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学生基础信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

